const rolloverIssues = `-- name: RolloverIssues :many
WITH locked AS MATERIALIZED (
    SELECT x.id FROM issues x
    JOIN workflow_states s ON s.org_id = x.org_id AND s.id = x.state_id
    WHERE x.org_id = $2 AND x.cycle_id = $3 AND x.archived_at IS NULL
      AND s.type NOT IN ('completed', 'canceled', 'triage')
    ORDER BY x.id
    FOR UPDATE OF x
)
UPDATE issues i
SET cycle_id = $1, version = i.version + 1, updated_at = now()
FROM locked
WHERE i.org_id = $2 AND i.id = locked.id
RETURNING i.id, i.number, i.version
`

type RolloverIssuesParams struct {
	ToCycleID   *uuid.UUID
	OrgID       uuid.UUID
	FromCycleID *uuid.UUID
}

type RolloverIssuesRow struct {
	ID      uuid.UUID
	Number  int32
	Version int32
}

// scope: system
// Moves the OPEN issues of one cycle to another: state type not completed
// or canceled or triage (LAUN-20: a triage issue is not planned work, so it
// stays where it is), and not archived. The state does not change, so no
// issue_state_changes row is written; version is bumped as for any change.
// The rows are locked in id order first (a CTE with FOR UPDATE, never
// inlined), the same order as RebalanceColumn, so the two cannot deadlock
// (decisions-T14 #10).
func (q *Queries) RolloverIssues(ctx context.Context, arg RolloverIssuesParams) ([]RolloverIssuesRow, error) {
	rows, err := q.db.Query(ctx, rolloverIssues, arg.ToCycleID, arg.OrgID, arg.FromCycleID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RolloverIssuesRow{}
	for rows.Next() {
		var i RolloverIssuesRow
		if err := rows.Scan(&i.ID, &i.Number, &i.Version); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

